/**
 * Opening the HTML files straight from disk (file://) — browsers refuse to
 * load font files there, so this copy of Yekan Bakh is embedded as data.
 * Only loaded in that case (see partials/head.html); never on the real site.
 */
(function () {
  var style = document.createElement("style");
  style.textContent =
    '@font-face{font-family:"Yekan Bakh Preview";font-weight:1 1000;font-display:swap;src:url(data:font/woff2;base64,) format("woff2")}' +
    // Unlayered, so it beats the theme value regardless of order
    ':root{--font-sans:"Yekan Bakh Preview","Yekan Bakh Fallback",Tahoma,sans-serif}';
  document.head.appendChild(style);
})();
